        const nx = x + dirs[dir][0]; const ny = y + dirs[dir][1];
        if (blocked.has(nx + ',' + ny)) break;
        x = nx; y = ny;
        best = Math.max(best, x * x + y * y);
      }
    }
  }
  return best;
}
