def solve(aliceSizes: list[int], bobSizes: list[int]) -> list[int]:
    sum_a = sum(aliceSizes)
    sum_b = sum(bobSizes)
    if (sum_a - sum_b) % 2 != 0:
        return []
    diff = (sum_a - sum_b) // 2
